package com.oratoria.backend.simulation.service;
import com.oratoria.backend.analysis.client.AiSpeechAnalysisClient;
import com.oratoria.backend.analysis.client.AiSpeechAnalysisClient.AiAnalysisClientException;
import com.oratoria.backend.auth.exception.InvalidCredentialsException;
import com.oratoria.backend.session.service.AudioStorageService;
import com.oratoria.backend.shared.exception.*;
import com.oratoria.backend.simulation.catalog.*;
import com.oratoria.backend.simulation.client.AiSimulationClient;
import com.oratoria.backend.simulation.client.AiSimulationClient.AiSimulationClientException;
import com.oratoria.backend.simulation.dto.SimulationDtos.*;
import com.oratoria.backend.simulation.entity.*;
import com.oratoria.backend.simulation.repository.*;
import com.oratoria.backend.user.entity.UserAccount;
import com.oratoria.backend.user.repository.UserAccountRepository;
import java.io.IOException;
import java.util.*;
import org.springframework.core.io.Resource;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.multipart.MultipartFile;
import tools.jackson.databind.ObjectMapper;

@Service
public class SimulationService {
 private final SimulationSessionRepository sessions; private final SimulationTurnRepository turns; private final UserAccountRepository users; private final SimulationScenarioCatalog catalog; private final AudioStorageService audioStorage; private final AiSpeechAnalysisClient speechClient; private final AiSimulationClient simulationClient; private final TransactionTemplate tx; private final ObjectMapper mapper;
 public SimulationService(SimulationSessionRepository sessions,SimulationTurnRepository turns,UserAccountRepository users,SimulationScenarioCatalog catalog,AudioStorageService audioStorage,AiSpeechAnalysisClient speechClient,AiSimulationClient simulationClient,TransactionTemplate tx,ObjectMapper mapper){this.sessions=sessions;this.turns=turns;this.users=users;this.catalog=catalog;this.audioStorage=audioStorage;this.speechClient=speechClient;this.simulationClient=simulationClient;this.tx=tx;this.mapper=mapper;}
 public List<ScenarioResponse> listScenarios(){return catalog.list().stream().map(s->new ScenarioResponse(s.id(),s.title(),s.description(),s.trainingType(),s.aiRole(),List.of(SimulationDifficulty.values()))).toList();}
 public SessionResponse create(String email,CreateRequest request){if(request==null)throw new BadRequestException("Debes seleccionar un escenario y dificultad.");UserAccount user=findUser(email);SimulationScenario sc=catalog.get(request.scenarioId());int max=switch(request.difficulty()){case BASIC->3;case INTERMEDIATE->4;case ADVANCED->5;};return tx.execute(x->{SimulationSession session=sessions.saveAndFlush(new SimulationSession(user,sc.id(),sc.trainingType(),request.difficulty(),max));turns.save(SimulationTurn.ai(session,1,sc.openingMessage()));return response(session);});}
 public List<SessionResponse> list(String email){UserAccount user=findUser(email);return sessions.findByUserIdOrderByCreatedAtDesc(user.getId()).stream().map(this::response).toList();}
 public SessionResponse get(String email,UUID id){return response(owned(findUser(email),id));}
 public SessionResponse respond(String email,UUID id,String idempotencyKey,MultipartFile audio,Integer duration){
  UserAccount user=findUser(email);validateKey(idempotencyKey);
  Reservation reservation=tx.execute(x->{SimulationSession s=ownedLocked(user,id);SimulationTurn duplicate=turns.findBySimulationIdAndIdempotencyKey(id,idempotencyKey).orElse(null);if(duplicate!=null){if(duplicate.getStatus()==SimulationTurnStatus.FAILED&&duplicate.getText()!=null&&!duplicate.getText().isBlank()&&(s.getStatus()==SimulationStatus.ACTIVE||s.getStatus()==SimulationStatus.READY_TO_FINISH)){s.beginProcessing();duplicate.retry();sessions.save(s);turns.save(duplicate);return new Reservation(s,duplicate,false,true);}return new Reservation(s,duplicate,true,false);}if(s.getStatus()!=SimulationStatus.ACTIVE)throw new BadRequestException("La simulación no acepta respuestas en su estado actual.");s.beginProcessing();sessions.save(s);int sequence=(int)turns.countBySimulationId(id)+1;SimulationTurn t=turns.saveAndFlush(SimulationTurn.userProcessing(s,sequence,idempotencyKey));return new Reservation(s,t,false,false);});
  if(reservation.duplicate())return response(reservation.session());
  SimulationTurn turn=reservation.turn();
  try{
   String transcript;
   if(reservation.resumed()){transcript=turn.getText();}else{AudioStorageService.StoredAudio stored=audioStorage.store(user.getId(),turn.getId(),audio,duration);tx.executeWithoutResult(x->{SimulationTurn t=turns.findById(turn.getId()).orElseThrow();t.attachAudio(stored.storagePath(),stored.mimeType(),stored.sizeBytes(),stored.originalFilename(),duration);turns.save(t);});Resource resource=audioStorage.loadAsResource(stored.storagePath());byte[] bytes=resource.getInputStream().readAllBytes();var speech=speechClient.analyzeSpeech(turn.getId(),bytes,stored.mimeType(),duration,stored.originalFilename());transcript=speech.transcriptText()==null?"":speech.transcriptText().trim();if(transcript.isBlank())throw new BadRequestException("No se detectó voz comprensible en la grabación.");String savedTranscript=transcript;tx.executeWithoutResult(x->{SimulationTurn t=turns.findById(turn.getId()).orElseThrow();t.attachTranscript(savedTranscript);turns.save(t);});}
   SimulationScenario sc=catalog.get(reservation.session().getScenarioId());List<AiHistoryMessage> history=history(id,false);AiReplyResponse reply=simulationClient.generateReply(new AiReplyRequest(id.toString(),sc.id(),sc.trainingType().name(),reservation.session().getDifficulty().name(),sc.aiRole(),sc.context(),sc.objective(),sc.rules(),history,transcript,reservation.session().getCurrentTurn()+1,reservation.session().getMaxTurns()));
   return tx.execute(x->{SimulationSession s=sessions.findById(id).orElseThrow();SimulationTurn t=turns.findById(turn.getId()).orElseThrow();t.complete(transcript);turns.save(t);turns.save(SimulationTurn.ai(s,t.getSequenceNumber()+1,reply.replyText()));s.completeTurn(reply.shouldEnd());sessions.save(s);return response(s);});
  }catch(AiAnalysisClientException e){fail(id,turn.getId(),e.getErrorCode(),e.getMessage());throw new BadRequestException(e.getMessage());}catch(AiSimulationClientException e){fail(id,turn.getId(),e.getErrorCode(),e.getMessage());throw new BadRequestException(e.getMessage());}catch(IOException e){fail(id,turn.getId(),"AUDIO_READ_ERROR","No se pudo leer el audio almacenado.");throw new IllegalStateException("No se pudo leer el audio almacenado.",e);}catch(BadRequestException e){fail(id,turn.getId(),"INVALID_AUDIO",e.getMessage());throw e;}
 }
 public SessionResponse finish(String email,UUID id){UserAccount user=findUser(email);FinishInput input=tx.execute(x->{SimulationSession s=ownedLocked(user,id);if(s.getStatus()==SimulationStatus.COMPLETED)return new FinishInput(s,null,true);if(s.getStatus()!=SimulationStatus.ACTIVE&&s.getStatus()!=SimulationStatus.READY_TO_FINISH)throw new BadRequestException("La simulación no puede finalizarse en su estado actual.");if(s.getCurrentTurn()<1)throw new BadRequestException("Responde al menos un turno antes de finalizar.");s.beginProcessing();sessions.save(s);return new FinishInput(s,history(id,true),false);});if(input.done())return response(input.session());
  SimulationScenario sc=catalog.get(input.session().getScenarioId());try{AiFeedbackResponse feedback=simulationClient.generateFeedback(new AiFeedbackRequest(id.toString(),sc.id(),sc.trainingType().name(),input.session().getDifficulty().name(),sc.context(),sc.objective(),input.history()));String json=write(feedback);return tx.execute(x->{SimulationSession s=sessions.findById(id).orElseThrow();s.complete(json,feedback.sufficientEvidence(),feedback.overallScore());sessions.save(s);return response(s);});}catch(AiSimulationClientException e){tx.executeWithoutResult(x->{SimulationSession s=sessions.findById(id).orElseThrow();s.restoreAfterFailure(e.getErrorCode(),e.getMessage());sessions.save(s);});throw new BadRequestException(e.getMessage());}
 }
 public FeedbackResponse feedback(String email,UUID id){SimulationSession s=owned(findUser(email),id);if(s.getStatus()!=SimulationStatus.COMPLETED)throw new BadRequestException("La retroalimentación final aún no está disponible.");return parseFeedback(s.getFinalFeedbackJson());}
 public AudioResource audio(String email,UUID simulationId,UUID turnId){SimulationSession s=owned(findUser(email),simulationId);SimulationTurn t=turns.findById(turnId).filter(v->v.getSimulation().getId().equals(s.getId())).orElseThrow(()->new ResourceNotFoundException("El turno solicitado no existe."));if(!t.hasAudio())throw new ResourceNotFoundException("El turno no tiene audio.");return new AudioResource(audioStorage.loadAsResource(t.getAudioStoragePath()),t.getAudioMimeType(),t.getAudioOriginalFilename());}
 private void fail(UUID sessionId,UUID turnId,String code,String message){tx.executeWithoutResult(x->{turns.findById(turnId).ifPresent(t->{t.fail(code,message);turns.save(t);});sessions.findById(sessionId).ifPresent(s->{s.restoreAfterFailure(code,message);sessions.save(s);});});}
 private List<AiHistoryMessage> history(UUID id,boolean includeProcessing){return turns.findBySimulationIdOrderBySequenceNumberAsc(id).stream().filter(t->t.getStatus()==SimulationTurnStatus.COMPLETED||(includeProcessing&&t.getText()!=null)).map(t->new AiHistoryMessage(t.getSpeaker().name(),t.getText())).toList();}
 private SessionResponse response(SimulationSession s){SimulationScenario sc=catalog.get(s.getScenarioId());List<TurnResponse> ts=turns.findBySimulationIdOrderBySequenceNumberAsc(s.getId()).stream().map(t->new TurnResponse(t.getId(),t.getSequenceNumber(),t.getSpeaker(),t.getStatus(),t.getText(),t.hasAudio(),t.getAudioDurationSeconds(),t.getErrorCode(),t.getErrorMessage(),t.getCreatedAt())).toList();return new SessionResponse(s.getId(),s.getScenarioId(),sc.title(),s.getTrainingType(),s.getDifficulty(),s.getStatus(),s.getCurrentTurn(),s.getMaxTurns(),ts,parseFeedback(s.getFinalFeedbackJson()),s.getErrorCode(),s.getErrorMessage(),s.getCreatedAt(),s.getCompletedAt());}
 private FeedbackResponse parseFeedback(String json){if(json==null||json.isBlank())return null;try{AiFeedbackResponse f=mapper.readValue(json,AiFeedbackResponse.class);return new FeedbackResponse(f.sufficientEvidence(),f.insufficientEvidenceReason(),f.overallScore(),f.summary(),safe(f.strengths()),safe(f.areasForImprovement()),safe(f.recommendations()),f.criteriaScores()==null?Map.of():f.criteriaScores());}catch(Exception e){return null;}}
 private String write(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("No se pudo guardar la retroalimentación.",e);}}
 private static <T>List<T> safe(List<T> v){return v==null?List.of():v;}
 private void validateKey(String key){if(key==null||key.isBlank()||key.length()>100)throw new BadRequestException("Debes enviar una clave Idempotency-Key válida.");}
 private UserAccount findUser(String email){if(email==null||email.isBlank())throw new InvalidCredentialsException();return users.findByEmailIgnoreCase(email.trim()).filter(UserAccount::isEnabled).orElseThrow(InvalidCredentialsException::new);}
 private SimulationSession owned(UserAccount user,UUID id){SimulationSession s=sessions.findById(id).orElseThrow(()->new ResourceNotFoundException("La simulación solicitada no existe."));if(!s.getUser().getId().equals(user.getId()))throw new AccessDeniedException("No tienes permiso para acceder a esta simulación.");return s;}
 private SimulationSession ownedLocked(UserAccount user,UUID id){SimulationSession s=sessions.findLockedById(id).orElseThrow(()->new ResourceNotFoundException("La simulación solicitada no existe."));if(!s.getUser().getId().equals(user.getId()))throw new AccessDeniedException("No tienes permiso para acceder a esta simulación.");return s;}
 private record Reservation(SimulationSession session,SimulationTurn turn,boolean duplicate,boolean resumed){} private record FinishInput(SimulationSession session,List<AiHistoryMessage> history,boolean done){} public record AudioResource(Resource resource,String mimeType,String filename){}
}
